 "3-48": {"id":"3-48","name":"マシュー・カルブレイス・ペリー","type":"ijin","color":"purple","colors":["purple"],"level":4,"power":3500,"traits":[],"legacy":null,"kw":{"voyage":true},"text":"手札から墓地に置かれたとき、これを戦場に置く。\n航海 - アタッカーになったとき、戦場か魔力ゾーンの裏のカード1つか2つを指定して発動できる。それらのカードの表を見る。","rarity":"R","unlimited":false,"set":"BP03"},
