 "2nd2-6": {"id":"2nd2-6","name":"徳川家康","type":"ijin","color":"green","colors":["green"],"level":5,"power":1000,"traits":[],"legacy":"draw1","kw":{},"text":"この能力は、自分の戦場のイジンがアタッカーになったとき、自分の魔力ゾーンの裏のカード1つを手札に戻して発動できる。自分の戦場のカードすべてを寝かせて、自分の戦場のアタッカーでないカード1つにつき1つ、相手の戦場のカードを寝かせる。","rarity":"SR","unlimited":false,"set":"BP06"},
